import { useId, type ReactNode, type Ref } from 'react'
import { Field } from '@base-ui/react/field'
import { Fieldset } from '@base-ui/react/fieldset'
import { Radio } from '@base-ui/react/radio'
import { RadioGroup as BaseRadioGroup } from '@base-ui/react/radio-group'
import { cn } from '@/lib/utils'
import { choiceStyles, type ValidationState } from './ChoiceField'
import styles from './Radio.module.css'

export interface RadioOption {
  value: string
  label: ReactNode
  helperText?: ReactNode
  disabled?: boolean
}

export interface RadioGroupProps {
  ref?: Ref<HTMLDivElement>
  options: RadioOption[]
  /** The group's legend. */
  label?: ReactNode
  /** Under the whole group; the error message when `validationState` is error. */
  helperText?: ReactNode
  value?: string
  defaultValue?: string
  /** The spec's `onChange`. Base UI's event details are dropped. */
  onValueChange?: (value: string) => void
  name?: string
  /** Colour of the selected radio. */
  variant?: 'primary' | 'secondary' | 'neutral'
  orientation?: 'vertical' | 'horizontal'
  disabled?: boolean
  required?: boolean
  readOnly?: boolean
  validationState?: ValidationState
  className?: string
  'aria-label'?: string
}

/**
 * A set of radios, one of which is selected. A radio is meaningless alone —
 * arrow keys move within its group — so the component is the group, with
 * the radios as flat `options`.
 */
export function RadioGroup({
  ref,
  options,
  label,
  helperText,
  name,
  variant = 'neutral',
  orientation = 'vertical',
  disabled,
  required,
  validationState = 'default',
  className,
  onValueChange,
  ...props
}: RadioGroupProps) {
  // Plain help describes the group once. An error message goes through Field,
  // which puts it on every radio: whichever one has focus, the reader hears
  // what is wrong.
  const helperId = useId()
  const isError = validationState === 'error'
  return (
    <Field.Root
      name={name}
      disabled={disabled}
      invalid={isError}
      className={cn(choiceStyles.field, choiceStyles[validationState], styles.field, className)}
    >
      <Fieldset.Root
        render={
          <BaseRadioGroup
            {...props}
            ref={ref}
            aria-describedby={helperText && !isError ? helperId : undefined}
            required={required}
            onValueChange={onValueChange && ((next) => onValueChange(next as string))}
          />
        }
        className={cn(styles.group, styles[orientation])}
      >
        {label && (
          <Fieldset.Legend className={styles.legend}>
            {label}
            {required && (
              <span aria-hidden="true" className={choiceStyles.required}>
                *
              </span>
            )}
          </Fieldset.Legend>
        )}
        {options.map((option) => (
          <Field.Item key={option.value} disabled={option.disabled} className={styles.item}>
            <Field.Label className={choiceStyles.label}>
              <Radio.Root
                value={option.value}
                className={cn(choiceStyles.control, styles.radio, styles[variant])}
              >
                <Radio.Indicator className={styles.dot} />
              </Radio.Root>
              {option.label}
            </Field.Label>
            {option.helperText && (
              <Field.Description className={cn(choiceStyles.helper, styles.optionHelper)}>
                {option.helperText}
              </Field.Description>
            )}
          </Field.Item>
        ))}
      </Fieldset.Root>
      {helperText &&
        (isError ? (
          <Field.Description className={cn(choiceStyles.helper, styles.groupHelper)}>
            {helperText}
          </Field.Description>
        ) : (
          <p id={helperId} className={cn(choiceStyles.helper, styles.groupHelper)}>
            {helperText}
          </p>
        ))}
    </Field.Root>
  )
}

.field {
  gap: var(--space-2);
}

/* A fieldset carries browser padding, border and margin, and its legend is
   positioned by the browser; reset them so the group lays out like a grid. */
.group {
  display: flex;
  gap: var(--space-2) var(--space-6);
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.vertical {
  flex-direction: column;
}

.horizontal {
  flex-flow: row wrap;
}

.legend {
  flex-basis: 100%;
  margin-block-end: var(--space-1);
  padding: 0;
  font-size: var(--text-body);
  line-height: var(--leading-body);
  font-weight: 500;
  color: var(--foreground);
}

.item {
  display: grid;
  gap: var(--space-1);
}

/* An option's own helper describes the option, so it stays muted when the
   group is in error or success; only the group message takes that colour.
   Three classes to outrank ChoiceField's `.error .helper`. */
.item .optionHelper.optionHelper {
  color: var(--muted-foreground);
}

/* Group helper text sits under the group, not indented under a control. */
.groupHelper.groupHelper {
  padding-inline-start: 0;
}

/* 16px circle, a --control-border outline (3:1 on the page). Selected fills
   with the variant and shows a dot in its label colour. */
.radio {
  --radio-fill: var(--foreground);
  --radio-dot: var(--background);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--space-4);
  block-size: var(--space-4);
  border: 1px solid var(--control-border);
  border-radius: 9999px;
  background: var(--background);
  cursor: var(--cursor-button);
}

.primary {
  --radio-fill: var(--primary);
  --radio-dot: var(--primary-foreground);
}

.secondary {
  --radio-fill: var(--secondary);
  --radio-dot: var(--secondary-foreground);
}

.radio[data-checked] {
  border-color: var(--radio-fill);
  background: var(--radio-fill);
}

/* The quiet variant keeps its outline, or a light circle vanishes. */
.secondary[data-checked] {
  border-color: var(--control-border);
}

.radio[data-invalid] {
  border-color: var(--danger-text);
}

.radio[data-readonly] {
  cursor: default;
}

/* 6px: a dot reads as "selected" at 16px without crowding the ring. */
.dot {
  inline-size: var(--space-1-5);
  block-size: var(--space-1-5);
  border-radius: 9999px;
  background: var(--radio-dot);
}
